cd /root/nanobot-src && python3 -c "
import json, os
# Check if there's a runtime config that stores agent ranks
for root, dirs, files in os.walk('.'):
    if '.git' in root or '__pycache__' in root or 'node_modules' in root:
        continue
    for f in files:
        if f.endswith('.json') or f.endswith('.yaml') or f.endswith('.yml'):
            path = os.path.join(root, f)
            try:
                with open(path) as fh:
                    content = fh.read()
                    if 'rank' in content and ('knight' in content or 'bishop' in content or 'queen' in content):
                        print(path)
            except:
                pass
" 2>/dev/null | head -20
